// Agent-driven delta -> main spec merge for change add-admin (inline /opsx:sync).
// Only ADDED and MODIFIED operations occur in this change's deltas; the script refuses anything else.
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = "/Users/elikafilin/Documents/home_projects/organic-shop-orchestrator/submissions/elika-filin";
const deltaDir = join(root, "openspec", "changes", "add-admin", "specs");
const specsDir = join(root, "openspec", "specs");
const capabilities = ["admin-auth", "admin-settings", "admin-web", "catalog-api", "catalog-web"];

const norm = (s) => s.replace(/\s+/g, " ").trim();

function sections(text) {
  const out = new Map();
  let cur = null;
  for (const line of text.split("\n")) {
    if (/^## /.test(line)) {
      cur = line.slice(3).trim();
      out.set(cur, []);
      continue;
    }
    if (cur !== null) out.get(cur).push(line);
  }
  return new Map([...out].map(([k, v]) => [k, v.join("\n")]));
}

function requirementBlocks(sectionText) {
  const blocks = [];
  let cur = null;
  for (const line of sectionText.split("\n")) {
    const m = line.match(/^### Requirement:\s*(.+?)\s*$/);
    if (m) {
      cur = { name: m[1], lines: [line] };
      blocks.push(cur);
      continue;
    }
    if (cur) cur.lines.push(line);
  }
  return blocks.map((b) => ({ name: b.name, text: b.lines.join("\n").replace(/\s+$/, "") }));
}

const scenarioNames = (blockText) =>
  [...blockText.matchAll(/^#### Scenario:\s*(.+?)\s*$/gm)].map((m) => norm(m[1]));

function splitMain(text) {
  const lines = text.split("\n");
  const idx = lines.findIndex((l) => l.trim() === "## Requirements");
  if (idx < 0) throw new Error("main spec has no ## Requirements section");
  const preamble = lines.slice(0, idx + 1).join("\n");
  const blocks = requirementBlocks(lines.slice(idx + 1).join("\n"));
  return { preamble, blocks };
}

const joinMain = (preamble, blocks) => `${preamble}\n\n${blocks.map((b) => b.text).join("\n\n")}\n`;

const summary = [];
for (const cap of capabilities) {
  const delta = readFileSync(join(deltaDir, cap, "spec.md"), "utf8");
  const sec = sections(delta);
  const known = new Set(["Purpose", "ADDED Requirements", "MODIFIED Requirements"]);
  for (const h of sec.keys()) if (!known.has(h)) throw new Error(`${cap}: unexpected delta section "${h}"`);
  const added = requirementBlocks(sec.get("ADDED Requirements") ?? "");
  const modified = requirementBlocks(sec.get("MODIFIED Requirements") ?? "");
  const mainPath = join(specsDir, cap, "spec.md");
  const notes = [];

  if (!existsSync(mainPath)) {
    if (modified.length) throw new Error(`${cap}: main spec missing but delta has MODIFIED requirements`);
    if (!added.length) throw new Error(`${cap}: main spec missing and delta has no ADDED requirements`);
    const purposeBody = (sec.get("Purpose") ?? "").replace(/^\n+|\s+$/g, "");
    if (!purposeBody) throw new Error(`${cap}: new capability without a usable ## Purpose`);
    if (purposeBody.length < 50) notes.push("WARNING: purpose shorter than 50 characters");
    const text = `# ${cap} Specification\n\n## Purpose\n\n${purposeBody}\n\n## Requirements\n\n${added.map((b) => b.text).join("\n\n")}\n`;
    mkdirSync(join(specsDir, cap), { recursive: true });
    writeFileSync(mainPath, text);
    notes.push(`created new spec with ${added.length} added requirement(s): ${added.map((b) => `"${b.name}"`).join(", ")}`);
    summary.push({ cap, notes });
    continue;
  }

  const main = readFileSync(mainPath, "utf8");
  const { preamble, blocks } = splitMain(main);
  const findIdx = (name) => blocks.findIndex((b) => norm(b.name) === norm(name));

  for (const m of modified) {
    const i = findIdx(m.name);
    if (i < 0) throw new Error(`${cap}: MODIFIED requirement "${m.name}" not found in main spec`);
    const before = scenarioNames(blocks[i].text);
    const after = scenarioNames(m.text);
    const dropped = before.filter((s) => !after.includes(s));
    if (dropped.length) throw new Error(`${cap}: MODIFIED "${m.name}" drops scenario(s): ${dropped.join("; ")}`);
    const newScenarios = after.filter((s) => !before.includes(s));
    blocks[i] = { name: blocks[i].name, text: m.text };
    notes.push(`modified "${m.name}" (kept ${before.length} scenario(s), added ${newScenarios.length}: ${newScenarios.join("; ")})`);
  }
  for (const a of added) {
    const i = findIdx(a.name);
    if (i >= 0) {
      blocks[i] = { name: blocks[i].name, text: a.text };
      notes.push(`updated existing "${a.name}" from ADDED (implicit MODIFIED)`);
    } else {
      blocks.push(a);
      notes.push(`added "${a.name}" (${scenarioNames(a.text).length} scenario(s))`);
    }
  }
  if (sec.has("Purpose")) notes.push("delta Purpose ignored: main spec already has one");
  writeFileSync(mainPath, joinMain(preamble, blocks));
  summary.push({ cap, notes });
}

for (const { cap, notes } of summary) {
  console.log(`${cap}:`);
  for (const n of notes) console.log(`  - ${n}`);
}

